/**
 * @element sp-action-button
 *
 * @slot - text label of the Action Button
 * @slot icon - The icon to use for Action Button
 * @fires change - Announces a change in the `selected` property of an action button
 * @fires longpress - Synthesizes a "longpress" interaction that signifies a
 * `pointerdown` event that is >=300ms or a keyboard event where code is `Space` or code is `ArrowDown`
 * while `altKey===true`.
 */
export class ActionButton extends SizedMixin(ButtonBase, {
  validSizes: ['xs', 's', 'm', 'l', 'xl'],
  noDefaultSize: true,
}) {
  public static override get styles(): CSSResultArray {
    return [...super.styles, buttonStyles, cornerTriangleStyles];
  }

  /**
   * @deprecated The `emphasized` property is deprecated and will be removed
   * in a future release.
   */
  @property({ type: Boolean, reflect: true })
  public get emphasized(): boolean {
    return this._emphasized;
  }
  public set emphasized(value: boolean) {
    const oldValue = this._emphasized;
    this._emphasized = value;
    this.requestUpdate('emphasized', oldValue);
    if (value && window.__swc?.DEBUG) {
      window.__swc.warn(
        this,
        `The "emphasized" attribute on <${this.localName}> is deprecated and will be removed in a future release.`,
        'https://opensource.adobe.com/spectrum-web-components/components/action-button/',
        { level: 'deprecation' }
      );
    }
  }
  private _emphasized = false;

  /**
   * Hold affordance is not included in the initial gen2 `swc-action-button`
   * release. It is planned for a future phase. See the action-button migration
   * plan for consumer options in the interim.
   */
  @property({ type: Boolean, reflect: true, attribute: 'hold-affordance' })
  public holdAffordance = false;

  @property({ type: Boolean, reflect: true })
  public quiet = false;

  @property({ reflect: true })
  public override role = 'button';

  /**
   * Whether an Action Button with `role='button'`
   * should also be `aria-pressed='true'`
   *
   * @deprecated The `selected` property is deprecated and will be removed in
   * a future release. Use `swc-toggle-button` for selectable button behavior.
   */
  @property({ type: Boolean, reflect: true })
  public get selected(): boolean {
    return this._selected;
  }
  public set selected(value: boolean) {
    const oldValue = this._selected;
    this._selected = value;
    this.requestUpdate('selected', oldValue);
    if (window.__swc?.DEBUG) {
      window.__swc.warn(
        this,
        `The "selected" attribute on <${this.localName}> is deprecated and will be removed in a future release.`,
        'https://opensource.adobe.com/spectrum-web-components/components/action-button/',
        { level: 'deprecation' }
      );
    }
  }
  private _selected = false;

  /**
   * Whether to automatically manage the `selected`
   * attribute on interaction and whether `aria-pressed="false"`
   * should be used when `selected === false`
   *
   * @deprecated The `toggles` property is deprecated and will be removed in
   * a future release. Use `swc-toggle-button` or `swc-toggle-button-group`
   * for toggle button behavior.
   */
  @property({ type: Boolean, reflect: true })
  public get toggles(): boolean {
    return this._toggles;
  }
  public set toggles(value: boolean) {
    const oldValue = this._toggles;
    this._toggles = value;
    this.requestUpdate('toggles', oldValue);
    if (value && window.__swc?.DEBUG) {
      window.__swc.warn(
        this,
        `The "toggles" attribute on <${this.localName}> is deprecated and will be removed in a future release.`,
        'https://opensource.adobe.com/spectrum-web-components/components/action-button/',
        { level: 'deprecation' }
      );
    }
  }
  private _toggles = false;

  /**
   * The static color variant to use for the action button.
   */
  @property({ reflect: true, attribute: 'static-color' })
  public staticColor?: 'white' | 'black';

  @property({ type: String })
  public get value(): string {
    return this._value || this.itemText;
  }
  public set value(value: string) {
    if (value === this._value) {
      return;
    }
    this._value = value || '';
    if (this._value) {
      this.setAttribute('value', this._value);
    } else {
      this.removeAttribute('value');
    }
  }
  private _value = '';

  /**
   * @private
   */
  public get itemText(): string {
    return (this.textContent || /* c8 ignore next */ '').trim();
  }

  constructor() {
    super();
    this.addEventListener('click', this.onClick);
  }

  private onClick = (): void => {
    if (!this.toggles) {
      return;
    }
    this.selected = !this.selected;
    const applyDefault = this.dispatchEvent(
      new Event('change', {
        cancelable: true,
        bubbles: true,
        composed: true,
      })
    );
    if (!applyDefault) {
      this.selected = !this.selected;
    }
  };

  private handlePointerdownHoldAffordance(event: PointerEvent): void {
    if (event.button !== 0) {
      return;
    }
    this.addEventListener('pointerup', this.handlePointerupHoldAffordance);
    this.addEventListener('pointercancel', this.handlePointerupHoldAffordance);
    LONGPRESS_TIMEOUT = setTimeout(() => {
      this.dispatchEvent(
        new CustomEvent<LongpressEvent>('longpress', {
          bubbles: true,
          composed: true,
          detail: {
            source: 'pointer',
          },
        })
      );
    }, LONGPRESS_DURATION);
  }

  private handlePointerupHoldAffordance(): void {
    clearTimeout(LONGPRESS_TIMEOUT);
    this.removeEventListener('pointerup', this.handlePointerupHoldAffordance);
    this.removeEventListener(
      'pointercancel',
      this.handlePointerupHoldAffordance
    );
  }

  /**
   * @private
   */
  protected override handleKeydown(event: KeyboardEvent): void {
    if (!this.holdAffordance) {
      return super.handleKeydown(event);
    }
    const { code, altKey } = event;
    if (code === 'Space' || (altKey && code === 'ArrowDown')) {
      event.preventDefault();
      if (code === 'ArrowDown') {
        event.stopImmediatePropagation();
      }
      this.addEventListener('keyup', this.handleKeyup);
      this.active = true;
    }
  }

  protected override handleKeyup(event: KeyboardEvent): void {
    if (!this.holdAffordance) {
      return super.handleKeyup(event);
    }
    const { code, altKey } = event;
    if (code === 'Space' || (altKey && code === 'ArrowDown')) {
      event.stopPropagation();
      this.dispatchEvent(
        new CustomEvent<LongpressEvent>('longpress', {
          bubbles: true,
          composed: true,
          detail: {
            source: 'keyboard',
          },
        })
      );
      this.active = false;
    }
  }

  protected override get buttonContent(): TemplateResult[] {
    const buttonContent = super.buttonContent;
    if (this.holdAffordance) {
      buttonContent.unshift(html`
        <sp-icon-corner-triangle300
          class="hold-affordance ${holdAffordanceClass[
            this.size as DefaultElementSize
          ]}"
        ></sp-icon-corner-triangle300>
      `);
    }
    return buttonContent;
  }

  protected override updated(changes: PropertyValues): void {
    super.updated(changes);
    const isButton = this.role === 'button';
    const canBePressed =
      isButton &&
      (this.selected || this.toggles) &&
      !(
        this.hasAttribute('aria-haspopup') && this.hasAttribute('aria-expanded')
      );
    if (changes.has('selected') || changes.has('role')) {
      // When role !== 'button' then the Action Button is within
      // an Action Group that manages selects which means the
      // Action Button is a "checkbox" or "radio" and cannot
      // accept the `aria-pressed` attribute.
      if (canBePressed) {
        this.setAttribute('aria-pressed', this.selected ? 'true' : 'false');
      } else {
        // When !this.toggles the lack of "aria-pressed" is inconsequential.
        this.removeAttribute('aria-pressed');
        if (isButton && this.toggles && this.hasAttribute('aria-expanded')) {
          this.setAttribute('aria-expanded', this.selected ? 'true' : 'false');
        }
      }
    }
    if (changes.has('holdAffordance')) {
      if (this.holdAffordance) {
        this.addEventListener(
          'pointerdown',
          this.handlePointerdownHoldAffordance
        );
      } else {
        this.removeEventListener(
          'pointerdown',
          this.handlePointerdownHoldAffordance
        );
        this.handlePointerupHoldAffordance();
      }
    }
  }
}

