  align = 'start',
  ariaLabel = 'More Actions',
  onChange = (() => undefined) as (value: string) => void,
  changeHandler = (() => undefined) as (value: string) => void,
  disabled = false,
  forcePopover = false,
  open = false,
  quiet = false,
  staticValue = '',
  visibleLabel = '',
