  title: 'Avatar',
  argTypes: {
    disabled: { control: 'boolean' },
    label: { control: 'text' },
    src: { control: 'text' },
    isDecorative: { control: 'boolean' },
  },
  args: {
    disabled: false,
    label: 'Place dog',
    src: avatar,
  },
};

interface StoryArgs {
  disabled?: boolean;
  label?: string;
  src?: string;
  size?: AvatarSize;
  isDecorative?: boolean;
}

const Template = ({
  label = 'Place Dog',
  src = avatar,
  size = 100,
  isDecorative = false,
}: StoryArgs = {}): TemplateResult => {
  return html`
    <sp-avatar
      label=${label}
      src=${src}
      size=${size}
      ?is-decorative=${isDecorative}
    ></sp-avatar>
  `;
};

const Link = ({
  disabled = false,
  label = 'Place Dog',
  src = avatar,
  size = 100,
}: StoryArgs = {}): TemplateResult => {
  return html`
    <sp-avatar
      href="https://opensource.adobe.com/spectrum-web-components"
      ?disabled=${disabled}
      label=${label}
      src=${src}
      size=${size}
    ></sp-avatar>
  `;
};

