import { StyledButton } from './StyledButton.js';

const crossIcon: Record<string, () => TemplateResult> = {
  s: () => html`
    <sp-icon-cross75
      slot="icon"
      class="icon spectrum-UIIcon-Cross75"
    ></sp-icon-cross75>
  `,
  m: () => html`
    <sp-icon-cross100
      slot="icon"
      class="icon spectrum-UIIcon-Cross100"
    ></sp-icon-cross100>
  `,
  l: () => html`
    <sp-icon-cross200
      slot="icon"
      class="icon spectrum-UIIcon-Cross200"
    ></sp-icon-cross200>
