import { html, TemplateResult } from '@spectrum-web-components/base';
import { ifDefined } from '@spectrum-web-components/base/src/directives.js';
import {
  ButtonTreatments,
  ButtonVariants,
} from '@spectrum-web-components/button/src/Button.js';

import '@spectrum-web-components/button/sp-clear-button.js';
import '@spectrum-web-components/button/sp-close-button.js';

export interface Properties {
  staticColor?: 'white' | 'black';
  variant?: ButtonVariants;
  treatment?: ButtonTreatments;
  quiet?: boolean;
  pending?: boolean;
  content?: TemplateResult;
  disabled?: boolean;
  size?: 's' | 'm' | 'l' | 'xl';

  /**
   * @deprecated Use a native HTML anchor (`<a>`) with the `spectrum-Button`
   * class and import `@spectrum-web-components/styles/global-elements.css`.
   */
  href?: string;
  target?: '_blank' | '_parent' | '_self' | '_top';
  noWrap?: boolean;
  iconOnly?: boolean;
  label?: string;
  minWidth?: string;
  componentName?: string;
}

export const Template = ({
  disabled,
  pending,
  size,
  treatment,
  variant,
  label = 'Clear',
  quiet,
  staticColor,
  componentName,
}: Properties): TemplateResult => {
  // Render clear-button for clear-button docs
  if (componentName === 'clear-button') {
    return html`
      <sp-clear-button
        label=${label}
        ?disabled=${!!disabled}
        ?quiet=${!!quiet}
        size=${ifDefined(size)}
        static-color=${ifDefined(staticColor)}
      ></sp-clear-button>
    `;
  }

  // Render close-button for close-button docs
  if (componentName === 'close-button') {
    return html`
      <sp-close-button
        label=${label}
        ?disabled=${!!disabled}
        ?quiet=${!!quiet}
        size=${ifDefined(size)}
        static-color=${ifDefined(staticColor)}
      ></sp-close-button>
    `;
  }

  // Default: render standard button
  return html`
    <sp-button
      ?disabled=${disabled}
      ?pending=${pending}
      size=${ifDefined(size)}
      treatment=${ifDefined(treatment)}
      variant=${ifDefined(variant)}
    >
      Test Button
    </sp-button>
  `;
};

