  box-sizing: border-box;
  display: inline-block;
  position: relative;
  inline-size: var(--mod-colorarea-width, var(--spectrum-color-area-width));
  min-inline-size: var(--mod-colorarea-min-width, var(--spectrum-color-area-minimum-width));
