export default {
  title: 'Dialog Wrapper',
  component: 'sp-dialog-wrapper',
  argTypes: {
    onClose: { action: 'close' },
    onConfirm: { action: 'confirm' },
    onSecondary: { action: 'secondary' },
    onCancel: { action: 'cancel' },
  },
};

type StoryArgs = {
  onClose?: (event: Event) => void;
  onConfirm?: (event: Event) => void;
  onSecondary?: (event: Event) => void;
  onCancel?: (event: Event) => void;
};

const handleClose =
  ({ onClose }: StoryArgs) =>
  (event: Event) => {
    if (onClose) {
      onClose(event);
    }
  };

const handleConfirm =
  ({ onConfirm }: StoryArgs) =>
  (event: Event) => {
    if (onConfirm) {
      onConfirm(event);
    }
  };

const handleSecondary =
  ({ onSecondary }: StoryArgs) =>
  (event: Event) => {
    if (onSecondary) {
      onSecondary(event);
    }
  };

const handleCancel =
  ({ onCancel }: StoryArgs) =>
  (event: Event) => {
    if (onCancel) {
      onCancel(event);
    }
  };

export const wrapperLabeledHero = (
  args: StoryArgs = {},
  context: { viewMode?: string } = {}
): TemplateResult => {
  const open = context.viewMode === 'docs' ? false : true;
  return html`
    <style>
      sp-story-decorator {
        inset: 0;
        position: absolute;
        overflow: hidden;
      }
    </style>
    <sp-dialog-wrapper
      ?open=${open}
      hero=${landscape}
      hero-label="Hero Image Alt Text"
      dismissable
      headline="Wrapped Dialog w/ Hero Image"
      @close=${handleClose(args)}
      size="s"
    >
      Content of the dialog
    </sp-dialog-wrapper>
    <sp-button
      onClick="
                this.previousElementSibling.open = !this.previousElementSibling.open;
                if (this.previousElementSibling.open) {
                    this.previousElementSibling.focus();
                }
            "
      variant="primary"
    >
      Toggle Dialog
    </sp-button>
  `;
};

