        style,
        unit,
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        unitDisplay,
        ...formatOptionsNoUnit
      } = this.formatOptions;
      if (style !== 'unit') {
        (formatOptionsNoUnit as Intl.NumberFormatOptions).style = style;
      }
      this._numberParserFocused = new NumberParser(
        this.languageResolver.language,
        formatOptionsNoUnit
