              @focusin=${this.handleFocusin}
              @focusout=${this.handleFocusout}
              ${streamingListener({
                start: ['pointerdown', this.handlePointerdown],
                streamInside: [
                  [
                    'pointermove',
                    'pointerenter',
                    'pointerleave',
                    'pointerover',
                    'pointerout',
                  ],
                  this.handlePointermove,
                ],
                end: [
                  ['pointerup', 'pointercancel', 'pointerleave'],
                  this.handlePointerup,
                ],
              })}
            >
              <sp-infield-button
                inline="end"
                block="start"
                class="button step-up"
                aria-hidden="true"
                label=${'Increase ' + this.appliedLabel}
                size=${this.size}
                tabindex="-1"
                ?focused=${this.focused}
                ?disabled=${this.disabled ||
                this.readonly ||
                (typeof this.max !== 'undefined' && this.value === this.max)}
                ?quiet=${this.quiet}
              >
                ${chevronIcon[this.size]('Up')}
              </sp-infield-button>
              <sp-infield-button
                inline="end"
                block="end"
                class="button step-down"
                aria-hidden="true"
                label=${'Decrease ' + this.appliedLabel}
                size=${this.size}
                tabindex="-1"
                ?focused=${this.focused}
                ?disabled=${this.disabled ||
                this.readonly ||
                (typeof this.min !== 'undefined' && this.value === this.min)}
                ?quiet=${this.quiet}
              >
                ${chevronIcon[this.size]('Down')}
              </sp-infield-button>
            </span>
