class ScrollForcer extends HTMLElement {
  ready!: (value: boolean | PromiseLike<boolean>) => void;

  constructor() {
    super();
    this.readyPromise = new Promise((res) => {
      this.ready = res;
    });
    this.setup();
  }

  async setup(): Promise<void> {
    await nextFrame();
    await nextFrame();

    this.previousElementSibling?.addEventListener('sp-opened', this.doScroll);
    await nextFrame();
    await nextFrame();
    (this.previousElementSibling?.lastElementChild as OverlayTrigger).open =
      'click';
  }

  doScroll = async (): Promise<void> => {
    this.previousElementSibling?.addEventListener('sp-opened', this.doScroll);
    await nextFrame();
    await nextFrame();
    await nextFrame();
    await nextFrame();

    if (document.scrollingElement) {
      document.scrollingElement.scrollTop = 100;
    }

    await nextFrame();
    await nextFrame();
    this.ready(true);
  };

  private readyPromise: Promise<boolean> = Promise.resolve(false);

  get updateComplete(): Promise<boolean> {
    return this.readyPromise;
  }
}

