class DefinedOverlayReady extends HTMLElement {
  ready!: (value: boolean | PromiseLike<boolean>) => void;

  connectedCallback(): void {
    if (this.ready !== undefined) {
      return;
    }

    this.readyPromise = new Promise((res) => {
      this.ready = res;
      this.setup();
    });
  }

  overlayElement!: OverlayTrigger;
  popoverElement!: PopoverContent;

  async setup(): Promise<void> {
    await nextFrame();
    await nextFrame();

    this.overlayElement = document.querySelector(
      `overlay-trigger`
    ) as OverlayTrigger;
    const button = document.querySelector(
      `[slot="trigger"]`
    ) as HTMLButtonElement;
    this.overlayElement.addEventListener('sp-opened', this.handleTriggerOpened);
    await nextFrame();
    await nextFrame();
    button.click();
  }

  handleTriggerOpened = async (): Promise<void> => {
    this.overlayElement.removeEventListener(
      'sp-opened',
      this.handleTriggerOpened
    );
    await nextFrame();
    await nextFrame();
    await nextFrame();
    await nextFrame();

    this.popoverElement = document.querySelector(
      'popover-content'
    ) as PopoverContent;
    if (!this.popoverElement) {
      return;
    }
    this.popoverElement.addEventListener('sp-opened', this.handlePopoverOpen);
    await nextFrame();
    await nextFrame();
    this.popoverElement.button.click();
  };

  handlePopoverOpen = async (): Promise<void> => {
    await nextFrame();

    this.ready(true);
  };

  disconnectedCallback(): void {
    this.overlayElement.removeEventListener(
      'sp-opened',
      this.handleTriggerOpened
    );
    this.popoverElement.removeEventListener(
      'sp-opened',
      this.handlePopoverOpen
    );
  }

  private readyPromise: Promise<boolean> = Promise.resolve(false);

  get updateComplete(): Promise<boolean> {
    return this.readyPromise;
  }
}

