import styles from './progress-bar.css.js';

/**
 * @element sp-progress-bar
 */
export class ProgressBar extends SizedMixin(
  ObserveSlotText(SpectrumElement, ''),
  {
    noDefaultSize: true,
  }
) {
  public static override get styles(): CSSResultArray {
    return [styles];
  }

  @property({ type: Boolean, reflect: true })
  public indeterminate = false;

  /**
   * @deprecated The `label` string attribute will be replaced by a `label`
   * named slot in a future release.
   */
  @property({ type: String, reflect: true })
  public label = '';

  private languageResolver = new LanguageResolutionController(this);

  /**
   * @deprecated Use "static-color='white'" instead.
   */
  @property({ type: Boolean, attribute: 'over-background' })
  public get overBackground(): boolean {
    return this._overBackground ? true : false;
  }

  public set overBackground(overBackground: boolean) {
    if (overBackground === true) {
      this.removeAttribute('over-background');
      this.staticColor = 'white';

      if (window.__swc?.DEBUG) {
        window.__swc.warn(
          this,
          `The "over-background" attribute on <${this.localName}> has been deprecated and will be removed in a future release. Use "static-color='white'" instead.`,
          'https://opensource.adobe.com/spectrum-web-components/components/progress-bar/#variants',
          {
            level: 'deprecation',
          }
        );
      }
    }
  }
  private _overBackground: boolean = false;

  /**
   * @deprecated The `side-label` attribute will be replaced by
   * `label-position="side"` in a future release.
   */
  @property({ type: Boolean, reflect: true, attribute: 'side-label' })
  public sideLabel = false;

  /**
   * @deprecated The `progress` property will be replaced by `value` in a
   * future release.
   */
  @property({ type: Number })
  public progress = 0;

  @property({ reflect: true, attribute: 'static-color' })
  public staticColor?: 'white';

  @query('slot')
  private slotEl!: HTMLSlotElement;

  protected override render(): TemplateResult {
    return html`
      ${this.slotHasContent || this.label
        ? html`
            <sp-field-label size=${this.size} class="label">
              ${this.slotHasContent ? nothing : this.label}
              <slot @slotchange=${this.handleSlotchange}></slot>
            </sp-field-label>
          `
        : nothing}
      ${this.label
        ? html`
            ${this.indeterminate
              ? nothing
              : html`
                  <sp-field-label size=${this.size} class="percentage">
                    ${this.formatProgress()}
                  </sp-field-label>
                `}
          `
        : nothing}
      <div class="track">
        <div
          class="fill"
          style="transform: scaleX(calc(${this.progress} / 100));"
        ></div>
      </div>
    `;
  }

  protected handleSlotchange(): void {
    const labelFromSlot = getLabelFromSlot(this.label, this.slotEl);
    if (labelFromSlot) {
      this.label = labelFromSlot;
    }
  }

  protected override firstUpdated(changes: PropertyValues): void {
    super.firstUpdated(changes);
    if (!this.hasAttribute('role')) {
      this.setAttribute('role', 'progressbar');
    }
  }

  private formatProgress(): string {
    return new Intl.NumberFormat(this.languageResolver.language, {
      style: 'percent',
      unitDisplay: 'narrow',
    }).format(this.progress / 100);
  }

  protected override updated(changes: PropertyValues): void {
    super.updated(changes);
    if (changes.has('indeterminate')) {
      if (this.indeterminate) {
        this.removeAttribute('aria-valuemin');
        this.removeAttribute('aria-valuemax');
        this.removeAttribute('aria-valuenow');
        this.removeAttribute('aria-valuetext');
      } else {
        this.setAttribute('aria-valuemin', '0');
        this.setAttribute('aria-valuemax', '100');
        this.setAttribute('aria-valuenow', '' + this.progress);
        this.setAttribute('aria-valuetext', this.formatProgress());
      }
    }
    if (!this.indeterminate && changes.has('progress')) {
      this.setAttribute('aria-valuenow', '' + this.progress);
      this.setAttribute('aria-valuetext', this.formatProgress());
    }
    if (!this.indeterminate && changes.has(languageResolverUpdatedSymbol)) {
      this.setAttribute('aria-valuetext', this.formatProgress());
    }
    if (changes.has('label')) {
      if (this.label.length) {
        this.setAttribute('aria-label', this.label);
      } else if (changes.get('label') === this.getAttribute('aria-label')) {
        this.removeAttribute('aria-label');
      }
    }

    if (window.__swc?.DEBUG) {
      if (changes.has('label') && this.label.length > 0) {
        window.__swc.warn(
          this,
          `The "label" attribute on <${this.localName}> has been deprecated and will be removed in a future release. Use a "label" named slot, or set "aria-label" or "aria-labelledby" on the element instead.`,
          'https://opensource.adobe.com/spectrum-web-components/components/progress-bar/#accessibility',
          { level: 'deprecation' }
        );
      }
      if (changes.has('sideLabel') && this.sideLabel) {
        window.__swc.warn(
          this,
          `The "side-label" attribute on <${this.localName}> has been deprecated and will be removed in a future release. Use label-position="side" instead.`,
          'https://opensource.adobe.com/spectrum-web-components/components/progress-bar/',
          { level: 'deprecation' }
        );
      }
      if (changes.has('progress') && this.progress !== 0) {
        window.__swc.warn(
          this,
          `The "progress" property on <${this.localName}> has been deprecated and will be removed in a future release. Use the "value" attribute instead.`,
          'https://opensource.adobe.com/spectrum-web-components/components/progress-bar/',
          { level: 'deprecation' }
        );
      }
    }

    if (window.__swc?.DEBUG) {
      if (
        !this.label &&
        !this.getAttribute('aria-label') &&
        !this.getAttribute('aria-labelledby') &&
        !this.slotHasContent
      ) {
        window.__swc.warn(
          this,
          '<sp-progress-bar> elements need one of the following to be accessible:',
          'https://opensource.adobe.com/spectrum-web-components/components/progress-bar/#accessibility',
          {
            type: 'accessibility',
            issues: [
              'value supplied to the "label" attribute, which will be displayed visually as part of the element, or',
              'text content supplied directly to the <sp-progress-bar> element, or',
              'value supplied to the "aria-label" attribute, which will only be provided to screen readers, or',
              'an element ID reference supplied to the "aria-labelledby" attribute, which will be provided by screen readers and will need to be managed manually by the parent application.',
            ],
          }
        );
      }
    }
  }
}

