  return html`
    <sp-table
      .size=${'m'}
      scroller
      style="height: 300px"
      selects=${ifDefined(args.selects)}
      .selected=${args.selected as string[]}
      @change=${({ target }: Event & { target: Table }) => {
        const next = target.nextElementSibling as HTMLDivElement;
        next.textContent = `Selected: ${JSON.stringify(target.selected)}`;
      }}
      .items=${virtualItems}
      .renderItem=${renderItem}
      @visibilityChanged=${(event: RangeChangedEvent) =>
        onChange({
          first: event.first,
          last: event.last,
          type: 'visibility',
        })}
      @rangeChanged=${(event: RangeChangedEvent) =>
        onChange({
          first: event.first,
          last: event.last,
          type: 'range',
        })}
    >
      <sp-table-head>
        <sp-table-head-cell>Column Title</sp-table-head-cell>
