  @property({ type: String })
  public set value(value: string | number) {
    if (value === this.value) {
      return;
    }
    const oldValue = this._value;
    this._value = value;
    this.requestUpdate('value', oldValue);
  }

  public get value(): string | number {
    return this._value;
  }

  protected _value: string | number = '';

