   * Note: combobox overrides `autocomplete` intentionally with `aria-autocomplete` values, which is
   * why those values (although invalid for native `autocomplete`) are included here to support the
   * combobox accessibility pattern.
   */
  @property({ type: String, reflect: true })
  public autocomplete?:
    | 'list'
    | 'none'
    | HTMLInputElement['autocomplete']
    | HTMLTextAreaElement['autocomplete'];

  public override get focusElement(): HTMLInputElement | HTMLTextAreaElement {
    return this.inputElement;
  }

  /**
   * Sets the start and end positions of the current selection.
   *
   * @param selectionStart The 0-based index of the first selected character. An index greater than the length of the
   *  element's value is treated as pointing to the end of the value.
   * @param selectionEnd The 0-based index of the character after the last selected character. An index greater than
   *  the length of the element's value is treated as pointing to the end of the value.
   * @param [selectionDirection="none"] A string indicating the direction in which the selection is considered to
   *  have been performed.
   */
  public setSelectionRange(
    selectionStart: number,
    selectionEnd: number,
    selectionDirection: 'forward' | 'backward' | 'none' = 'none'
  ): void {
    this.inputElement.setSelectionRange(
      selectionStart,
      selectionEnd,
      selectionDirection
    );
  }

  /**
   * Selects all the text.
   */
  public select(): void {
    this.inputElement.select();
  }

  protected handleInput(_event: Event): void {
    if (this.allowedKeys && this.inputElement.value) {
      const regExp = new RegExp(`^[${this.allowedKeys}]*$`, 'u');
      if (!regExp.test(this.inputElement.value)) {
        const selectionStart = this.inputElement.selectionStart as number;
        const nextSelectStart = selectionStart - 1;
        this.inputElement.value = this.value.toString();
        this.inputElement.setSelectionRange(nextSelectStart, nextSelectStart);
        return;
      }
    }
    this.value = this.inputElement.value;
  }

  protected handleChange(): void {
    this.dispatchEvent(
      new Event('change', {
        bubbles: true,
        composed: true,
      })
    );
  }

  protected onFocus(): void {
    this.focused = !this.readonly && true;
  }

  protected onBlur(_event: FocusEvent): void {
    this.focused = !this.readonly && false;
  }

  protected handleInputElementPointerdown(): void {}

  protected renderStateIcons(): TemplateResult | typeof nothing {
    if (this.invalid) {
      return html`
        <sp-icon-alert id="invalid" class="icon"></sp-icon-alert>
      `;
    } else if (this.valid) {
      return html`
        <sp-icon-checkmark100
          id="valid"
          class="icon spectrum-UIIcon-Checkmark100"
        ></sp-icon-checkmark100>
      `;
    }
    return nothing;
  }

  protected get displayValue(): string {
    return this.value.toString();
  }

  // prettier-ignore
  private get renderMultiline(): TemplateResult {
        return html`
            ${this.multiline && this.grows && this.rows === -1
                ? html`
                      <div id="sizer" class="input" aria-hidden="true">${this.value}&#8203;
                      </div>
                  `
                : nothing}
            <!-- @ts-ignore -->
            <textarea
                name=${ifDefined(this.name || undefined)}
                aria-describedby=${this.helpTextId}
                aria-label=${ifDefined(
                    this.label || this.appliedLabel || this.placeholder || undefined
                )}
                aria-invalid=${ifDefined(this.invalid || undefined)}
                class="input"
                maxlength=${ifDefined(
                    this.maxlength > -1 ? this.maxlength : undefined
                )}
                minlength=${ifDefined(
                    this.minlength > -1 ? this.minlength : undefined
                )}
                title=${this.invalid ? '' : nothing}
                pattern=${ifDefined(this.pattern)}
                placeholder=${this.placeholder}
                .value=${this.displayValue}
                @change=${this.handleChange}
                @input=${this.handleInput}
                @focus=${this.onFocus}
                @blur=${this.onBlur}
                ?disabled=${this.disabled}
                ?required=${this.required}
                ?readonly=${this.readonly}
                rows=${ifDefined(this.rows > -1 ? this.rows : undefined)}
                autocomplete=${ifDefined(this.autocomplete)}
            ></textarea>
        `;
    }

  private get renderInput(): TemplateResult {
    return html`
      <!-- @ts-ignore -->
      <input
        name=${ifDefined(this.name || undefined)}
        type=${this.type}
        aria-describedby=${this.helpTextId}
        aria-label=${ifDefined(
          this.label || this.appliedLabel || this.placeholder || undefined
        )}
        aria-invalid=${ifDefined(this.invalid || undefined)}
        class="input"
        title=${this.invalid ? '' : nothing}
        maxlength=${ifDefined(this.maxlength > -1 ? this.maxlength : undefined)}
        minlength=${ifDefined(this.minlength > -1 ? this.minlength : undefined)}
        pattern=${ifDefined(this.pattern)}
        placeholder=${this.placeholder}
        .value=${live(this.displayValue)}
        @change=${this.handleChange}
        @input=${this.handleInput}
        @pointerdown=${this.handleInputElementPointerdown}
        @focus=${this.onFocus}
        @blur=${this.onBlur}
        ?disabled=${this.disabled}
        ?required=${this.required}
        ?readonly=${this.readonly}
        autocomplete=${ifDefined(this.autocomplete)}
      />
    `;
  }

  protected renderField(): TemplateResult {
    return html`
      ${this.renderStateIcons()}
      ${this.multiline ? this.renderMultiline : this.renderInput}
    `;
  }

  protected override render(): TemplateResult {
    return html`
      <div id="textfield">${this.renderField()}</div>
      ${this.truncatedValueTooltipController.render()}
      ${this.renderHelpText(this.invalid)}
    `;
  }

  protected override update(changedProperties: PropertyValues): void {
    const valueOrRequiredChanged =
      changedProperties.has('value') ||
      (changedProperties.has('required') && this.required);

    if (valueOrRequiredChanged) {
      this.updateComplete.then(() => {
        this.checkValidity();
        if (changedProperties.has('value')) {
          // Truncation tooltip uses an intentional multi-phase update: (1) first render puts value in
          // DOM, (2) after updateComplete we measure and set truncation state, (3) controller defers
          // requestUpdate to a microtask so a second render shows the tooltip. We cannot show the
          // tooltip in the first render because we must measure after layout. This can cause a brief
          // delay before the tooltip appears; that is expected.
          this.truncatedValueTooltipController.refresh();
        }
      });
    }

    super.update(changedProperties);

    if (changedProperties.has('focused') && !this.focused) {
      this.truncatedValueTooltipController.refresh();
    }
  }

  public checkValidity(): boolean {
    let validity = this.inputElement.checkValidity();
    if (this.required || (this.value && this.pattern)) {
      if ((this.disabled || this.multiline) && this.pattern) {
        const regex = new RegExp(`^${this.pattern}$`, 'u');
        validity = regex.test(this.value.toString());
      }
      if (typeof this.minlength !== 'undefined') {
        validity = validity && this.value.toString().length >= this.minlength;
      }
      this.valid = validity;
      this.invalid = !validity;
    }
    return validity;
  }
}

/**
 * @element sp-textfield
 * @slot help-text - default or non-negative help text to associate to your form element
 * @slot negative-help-text - negative help text to associate to your form element when `invalid`
 */
export class Textfield extends TextfieldBase {
  @property({ type: String })
  public override set value(value: string) {
    if (value === this.value) {
      return;
    }
    const oldValue = this._value;
    this._value = value;
    this.requestUpdate('value', oldValue);
  }

  public override get value(): string {
    return this._value;
  }

  protected override _value = '';
}

